'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { careerApi } from '@/lib/api/career';
import { candidatesApi } from '@/lib/api/candidates';
import { useCareerText } from '@/lib/i18n/career';
import { useReleaseText } from '@/lib/i18n/release';
import { AtsPanel, Busy, Failure, Field, JobCard, FeatureGate } from '@/components/candidate/career-shared';
import { ProfessionalDetails } from '@/components/candidate/career-pages';
import { ProfilePhoto } from '@/components/candidate/profile-photo';
import { FaceEnrollment } from './face-enrollment';
import { useEntitlement } from '@/hooks/use-entitlement';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { EasyJobCoach } from './easyjob-coach';
import { ProfilePreparation } from './profile-preparation';
import { Dialog, DialogContent, DialogDescription, DialogTitle } from '@/components/ui/dialog';
import { toast } from 'sonner';
interface Props { candidateEmail: string; candidatePhone?: string; initialResumeId?: string; onFinishFace: () => void; onFinishDashboard: () => void }
export function CandidateCvOnboarding({ candidateEmail, candidatePhone, initialResumeId, onFinishDashboard }: Props) {
  const t = useCareerText(), tr = useReleaseText(), qc = useQueryClient(), ent = useEntitlement('CANDIDATE');
  const detailsSave = useRef<(() => Promise<unknown>) | null>(null);
  const [step, setStep] = useState(0), [id] = useState(initialResumeId ?? ''), [faceDone, setFaceDone] = useState(false), [upgradeOpen, setUpgradeOpen] = useState(false);
  const [fields, setFields] = useState<Record<string, string>>({}), [domains, setDomains] = useState(''), [locations, setLocations] = useState(''), [remote, setRemote] = useState(false);
  const [manualReview, setManualReview] = useState(false), [stalled, setStalled] = useState(false);
  const report = useQuery({ queryKey: ['career-onboarding', id], queryFn: () => careerApi.report(id), enabled: !!id && !manualReview,
    refetchInterval: q => !manualReview && !q.state.error && (!q.state.data || ['PENDING', 'PROCESSING'].includes(q.state.data.status)) ? 2000 : false });
  const profile = useQuery({ queryKey: ['candidate-profile'], queryFn: () => candidatesApi.me(), enabled: step === 0 });
  useEffect(() => {
    document.body.dataset.authOnboarding = 'true';
    window.dispatchEvent(new Event('easyjob:onboarding-toggle'));
    return () => {
      delete document.body.dataset.authOnboarding;
      window.dispatchEvent(new Event('easyjob:onboarding-toggle'));
    };
  }, []);
  useEffect(() => {
    if (step !== 0) return;
    const extracted = report.data?.extracted;
    const firstValue = (...values: (string | null | undefined)[]) => values.find(value => typeof value === 'string' && value.trim()) ?? '';
    setFields(current => ({
      headline: current.headline?.trim() ? current.headline : firstValue(profile.data?.headline, extracted?.headline),
      phone: current.phone?.trim() ? current.phone : firstValue(profile.data?.phone, extracted?.phone, candidatePhone),
      location: current.location?.trim() ? current.location : firstValue(profile.data?.location, extracted?.location),
    }));
  }, [candidatePhone, profile.data, report.data?.extracted, step]);
  useEffect(() => {
    if (report.data?.status === 'COMPLETED') {
      for (const key of ['candidate-profile', 'career-profile-details', 'career-overview']) void qc.invalidateQueries({ queryKey: [key] });
    }
  }, [report.data?.status, qc]);
  useEffect(() => { if (step === 6) setUpgradeOpen(true); }, [step]);
  const domainSuggestions = useMemo(() => {
    const extracted = report.data?.extracted;
    return [...new Set([
      extracted?.headline,
      ...(extracted?.experiences ?? []).map(entry => entry.title),
      ...(extracted?.sections?.skills ?? []).slice(0, 3),
    ].map(value => value?.trim()).filter((value): value is string => !!value))].slice(0, 4);
  }, [report.data?.extracted]);
  const addDomainSuggestion = (value: string) => setDomains(current => [...new Set([...current.split(/[,،]/).map(item => item.trim()).filter(Boolean), value])].join(', '));
  const openUpgradeAssistant = () => setUpgradeOpen(true);
  const chooseUpgrade = () => { setUpgradeOpen(false); toast.success(t('assistantGreat')); window.location.assign('/candidate/subscription'); };
  const chooseLater = () => { setUpgradeOpen(false); if (step === 6) { toast.success(t('assistantThanks')); onFinishDashboard(); } };
  const recommendations = useQuery({ queryKey: ['onboarding-recommendations'], queryFn: () => careerApi.jobs({ limit: 3 }, true), enabled: step === 5 && ent.feature('career.match') === true });
  const next = useMutation({ mutationFn: async () => {
    if (step === 0) { if (Object.keys(fields).length) await candidatesApi.updateMe(fields); await detailsSave.current?.(); }
    if (step === 4) await careerApi.saveSettings({ domains: domains.split(/[,،]/).map(s => s.trim()).filter(Boolean), locations: locations.split(/[,،]/).map(s => s.trim()).filter(Boolean), workModes: remote ? ['REMOTE'] : [] });
  }, onSuccess: () => { if (step === 0) void qc.invalidateQueries({ queryKey: ['candidate-profile'] }); setStep(s => Math.min(6, s + 1)); } });
  const titles = [t('reviewExtracted'), t('ats'), tr('Votre photo', 'Your photo', 'صورتك'), 'Face ID', t('jobPreferences'), t('recommended'), t('subscription')];
  const waitingForResume = !!id && !manualReview && report.data?.status !== 'COMPLETED';
  const preparing = step === 0 && (!profile.data || waitingForResume);
  const preparationFailed = profile.isError || (!manualReview && !!id && (report.isError || report.data?.status === 'FAILED'));
  useEffect(() => {
    if (!preparing) return;
    const timeout = setTimeout(() => setStalled(true), 90_000);
    return () => clearTimeout(timeout);
  }, [preparing]);
  if (preparing) return <ProfilePreparation stalled={stalled} failed={preparationFailed} hasResume={!!id}
    onCheck={() => { void profile.refetch(); if (id) void report.refetch(); }}
    onManual={profile.data ? () => setManualReview(true) : undefined} />;
  const waiting = step === 1 && !manualReview && !!id && ['PENDING', 'PROCESSING'].includes(report.data?.status ?? '');
  return <section className="space-y-6">
    <div><p className="mb-3 text-xs font-medium text-primary">{t('yourJourney')} · {step + 1} / {titles.length}</p><div className="flex gap-1" role="progressbar" aria-label={t('yourJourney')} aria-valuemin={1} aria-valuemax={titles.length} aria-valuenow={step + 1}>{titles.map((_, i) => <span key={i} className={`h-1.5 flex-1 rounded-full ${i <= step ? 'bg-indigo-500' : 'bg-muted'}`} />)}</div></div>
    <h2 className="text-2xl font-semibold tracking-tight">{titles[step]}</h2>
    {step === 0 && <div className="space-y-5"><p className="text-sm text-muted-foreground">{candidateEmail}</p>{(['headline', 'phone', 'location'] as const).map(key => <Field key={key} label={t(key)}><Input type={key === 'phone' ? 'tel' : 'text'} maxLength={key === 'phone' ? 30 : 120} value={fields[key] ?? ''} onChange={e => setFields(f => ({ ...f, [key]: e.target.value }))} /></Field>)}<ProfessionalDetails fallback={report.data?.extracted ?? undefined} onRegisterSave={save => { detailsSave.current = save; }} /></div>}
    {step === 1 && (report.data?.report ? <AtsPanel report={report.data.report} profile={report.data.extracted ?? undefined} onImprove={openUpgradeAssistant} /> : <p className="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">{t('noCv')}</p>)}
    {step === 2 && <ProfilePhoto />}
    {step === 3 && (faceDone ? <p role="status">{tr('Face ID est enregistré.', 'Face ID is enrolled.', 'تم تسجيل الوجه.')}</p> : <FaceEnrollment onDone={() => setFaceDone(true)} onReferenceFrame={(frame) => candidatesApi.uploadPhoto(frame)} onCancel={() => setStep(4)} />)}
    {step === 4 && <div className="space-y-4"><Field label={t('domain')}><Input placeholder={t('comma')} value={domains} onChange={e => setDomains(e.target.value)} /></Field>{domainSuggestions.length > 0 && <div className="space-y-2"><p className="text-xs text-muted-foreground">{t('domainSuggestions')}</p><div className="flex flex-wrap gap-2">{domainSuggestions.map(value => <button type="button" key={value} onClick={() => addDomainSuggestion(value)} className="rounded-full border border-indigo-300/60 bg-indigo-50/60 px-3 py-1 text-xs font-medium text-indigo-700 transition hover:border-indigo-500 dark:border-indigo-800 dark:bg-indigo-950/40 dark:text-indigo-200">+ {value}</button>)}</div></div>}<Field label={t('location')}><Input value={locations} onChange={e => setLocations(e.target.value)} /></Field><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={remote} onChange={e => setRemote(e.target.checked)} />{t('REMOTE')}</label></div>}
    {step === 5 && <FeatureGate feature="career.match">{recommendations.isPending ? <Busy /> : recommendations.isError ? <Failure retry={() => recommendations.refetch()} /> : recommendations.data?.items.length ? <div className="space-y-3">{recommendations.data.items.map(j => <JobCard key={j.id} job={j} />)}</div> : <p>{t('emptyRecommendations')}</p>}</FeatureGate>}
    <Dialog open={upgradeOpen} onOpenChange={open => { if (!open) chooseLater(); else setUpgradeOpen(true); }}><DialogContent className="!top-1/2 !bottom-auto !w-[min(94vw,960px)] !max-w-none !-translate-y-1/2 !max-h-[92dvh] !rounded-3xl overflow-y-auto gap-0 border-indigo-300/40 bg-slate-950 !p-0 text-slate-100"><DialogTitle className="sr-only">{t('assistantTitle')}</DialogTitle><DialogDescription className="sr-only">{t('assistantBody')}</DialogDescription><EasyJobCoach onUpgrade={chooseUpgrade} onLater={chooseLater} finalStep={step === 6} /></DialogContent></Dialog>
    {next.isError && <p role="alert" className="text-destructive">{t('error')}</p>}
    <div className="flex flex-wrap gap-2 border-t pt-5"><Button variant="outline" disabled={step === 0 || next.isPending} onClick={() => setStep(s => s - 1)}>{t('previous')}</Button>{step < 6 ? <Button disabled={!!waiting || next.isPending} onClick={() => next.mutate()}>{next.isPending ? t('PROCESSING') : step === 3 && !faceDone ? t('skipForNow') : t('next')}</Button> : <Button onClick={onFinishDashboard}>{t('dashboard')}</Button>}</div>
  </section>;
}


