'use client';
import { useState } from 'react';
import { useMutation, useQuery } from '@tanstack/react-query';
import { api } from '@/lib/api/client';
import { env } from '@/config/env';
import { useReleaseText } from '@/lib/i18n/release';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
export function ProfilePhoto() {
  const t = useReleaseText(), [error, setError] = useState(''), [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const photo = useQuery({ queryKey: ['candidate-photo'], queryFn: () => api.get<{ url: string | null }>('/candidates/me/photo'), staleTime: 0, gcTime: 0 });
  const save = useMutation({ mutationFn: (file: File) => { const body = new FormData(); body.append('file', file); return api.post('/candidates/me/photo', body); }, onSuccess: () => photo.refetch(), onError: () => setError(t('Photo non enregistrée. Choisissez un fichier PNG, JPEG ou WebP de moins de 5 Mo.', 'Photo not saved. Choose a PNG, JPEG or WebP under 5 MB.', 'لم تُحفظ الصورة. اختر PNG أو JPEG أو WebP أقل من 5 ميغابايت.')) });
  const remove = useMutation({ mutationFn: () => api.delete('/candidates/me/photo'), onSuccess: () => photo.refetch(), onError: () => setError(t('Suppression impossible. Réessayez.', 'Unable to remove photo. Try again.', 'تعذّر حذف الصورة. حاول مجددًا.')) });
  const imageUrl = photo.data?.url ? (photo.data.url.startsWith('http') ? photo.data.url : new URL(photo.data.url, env.apiUrl).toString()) : null;
  return <section className="space-y-4 rounded-2xl border bg-card p-5"><h2 className="font-semibold">{t('Votre photo', 'Your photo', 'صورتك')}</h2><p className="text-sm text-muted-foreground">{t('Ajoutez une photo à votre profil. La photo centrale validée pendant Face ID peut aussi être enregistrée automatiquement ici.', 'Add a profile photo. The verified center frame from Face ID can also be saved here automatically.', 'أضف صورة للملف الشخصي. يمكن أيضًا حفظ الصورة المركزية التي تم التحقق منها أثناء Face ID هنا تلقائيًا.')}</p>
    {(previewUrl || imageUrl) && <img src={previewUrl || imageUrl || ''} alt={t('Votre photo de profil', 'Your profile photo', 'صورة ملفك الشخصي')} className="size-32 rounded-full border-2 border-primary/30 object-cover" referrerPolicy="no-referrer" />}
    <Input type="file" accept="image/png,image/jpeg,image/webp" aria-label={t('Ajouter une photo', 'Upload photo', 'إضافة صورة')} disabled={save.isPending || remove.isPending} onChange={e => { const file = e.target.files?.[0]; e.target.value = ''; setError(''); if (!file) return; if (file.size > 5 * 1024 * 1024) { setError(t('Maximum 5 Mo.', 'Maximum 5 MB.', 'الحد الأقصى 5 ميغابايت.')); return; } setPreviewUrl(URL.createObjectURL(file)); save.mutate(file); }} />
    {save.isPending && <p role="status">{t('Enregistrement…', 'Saving…', 'جارٍ الحفظ…')}</p>}
    {(previewUrl || imageUrl) && <Button variant="outline" disabled={remove.isPending || save.isPending} onClick={() => { setPreviewUrl(null); remove.mutate(); }}>{t('Supprimer la photo', 'Remove photo', 'حذف الصورة')}</Button>}
    {(error || photo.isError) && <p role="alert" className="text-sm text-destructive">{error || t('Impossible de charger la photo.', 'Unable to load photo.', 'تعذّر تحميل الصورة.')}</p>}
  </section>;
}
