'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { zodResolver } from '@hookform/resolvers/zod';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { toast } from 'sonner';
import { ArrowRight, FileUp, MailCheck } from 'lucide-react';
import { authApi } from '@/lib/api/auth';
import { resumesApi } from '@/lib/api/resumes';
import { establishSession } from '@/lib/auth-session';
import { useAuthStore } from '@/store/auth-store';
import { ApiError } from '@/lib/api/client';
import { env } from '@/config/env';
import { Input } from '@/components/ui/input';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { CandidateCvOnboarding } from './candidate-cv-onboarding';
import { useReleaseText } from '@/lib/i18n/release';

const schema = z.object({
  name: z.string().min(2, 'Name must be at least 2 characters').max(120, 'Name is too long'),
  email: z.string().email('Enter a valid email address'),
  password: z
    .string()
    .min(8, 'Password must be at least 8 characters')
    .max(72, 'Password must be 72 characters or fewer')
    .regex(/[a-z]/, 'Password must contain a lowercase letter')
    .regex(/[A-Z]/, 'Password must contain an uppercase letter')
    .regex(/[0-9]/, 'Password must contain a digit'),
  phone: z.string().max(30, 'Phone is too long').optional().or(z.literal('')),
  website: z.string().optional().or(z.literal('')),
});

type FormValues = z.infer<typeof schema>;

export function RegisterForm() {
  const tr = useReleaseText();
  const router = useRouter();
  const searchParams = useSearchParams();
  useEffect(() => {
    if (searchParams.get('intent') !== 'company') return;
    const frame = window.requestAnimationFrame(() => router.replace('/company/register'));
    return () => window.cancelAnimationFrame(frame);
  }, [router, searchParams]);
  const [selectedRole] = useState<'candidate' | 'company'>('candidate');
  const setLastEmail = useAuthStore((s) => s.setLastEmail);
  const [candidateStep2, setCandidateStep2] = useState(false);
  const [registeredEmail, setRegisteredEmail] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isOffline, setIsOffline] = useState(false);
  const [isDuplicate, setIsDuplicate] = useState(false);
  const [cvFile, setCvFile] = useState<File | null>(null);
  const [prefillMode, setPrefillMode] = useState<'upload' | 'manual'>('upload');
  const [initialResumeId, setInitialResumeId] = useState<string | undefined>();

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { name: '', email: '', password: '', phone: '', website: '' },
  });

  const onSubmit = async (values: FormValues) => {
    setError(null);
    setIsOffline(false);
    setIsDuplicate(false);
    try {
      await authApi.register({
        name: values.name,
        email: values.email,
        password: values.password,
        phone: values.phone || undefined,
        intent: selectedRole,
      });

      setLastEmail(values.email);

      if (selectedRole === 'candidate') {
        const login = await authApi.login({ email: values.email, password: values.password });
        await establishSession(login.accessToken, values.email);
        // Upload a CV selected during registration so the profile can be
        // prefilled immediately. If the upload fails, the onboarding flow
        // remains available and lets the candidate retry it there.
        if (prefillMode === 'upload' && cvFile) {
          try {
            const resume = await resumesApi.upload(cvFile);
            setInitialResumeId(resume.id);
          } catch {
            toast.error('Compte créé, mais le CV n’a pas pu être importé. Tu peux réessayer à l’étape suivante.');
          }
        }
        setCandidateStep2(true);
      } else {
        // Company flow — direct to email verification / company dashboard
        setRegisteredEmail(values.email);
        toast.success('Company account created — check your email to verify it');
      }
    } catch (err) {
      let message = 'Registration failed';
      let isConnError = false;
      let isDupError = false;

      if (err instanceof ApiError) {
        if (err.status === 0 || err.message.includes('connect') || err.message.includes('fetch')) {
          isConnError = true;
          message = `Backend API server (${env.apiUrl}) is currently offline or unreachable.`;
        } else {
          const bodyMsg = (err.body as { message?: string | string[] } | null)?.message;
          let rawMsg = '';
          if (Array.isArray(bodyMsg)) {
            rawMsg = bodyMsg.join(', ');
          } else if (typeof bodyMsg === 'string' && bodyMsg.trim().length > 0) {
            rawMsg = bodyMsg;
          } else if (err.message) {
            rawMsg = err.message;
          }

          if (
            err.status === 409 ||
            rawMsg.toLowerCase().includes('unique value') ||
            rawMsg.toLowerCase().includes('already exists')
          ) {
            isDupError = true;
            message = 'An account with this email address already exists. Please log in or use a different email.';
          } else {
            message = rawMsg || 'Registration failed';
          }
        }
      } else if (err instanceof Error) {
        if (err.message.includes('fetch') || err.message.includes('connect')) {
          isConnError = true;
          message = `Backend API server (${env.apiUrl}) is currently offline or unreachable.`;
        } else if (
          err.message.toLowerCase().includes('unique value') ||
          err.message.toLowerCase().includes('already exists')
        ) {
          isDupError = true;
          message = 'An account with this email address already exists. Please log in or use a different email.';
        } else {
          message = err.message;
        }
      }

      setIsOffline(isConnError);
      setIsDuplicate(isDupError);
      setError(message);
    }
  };

  // Candidate Step 2+: CV Upload & AI Auto-Prefill Flow
  if (selectedRole === 'candidate' && candidateStep2) {
    return (
      <CandidateCvOnboarding
        candidateEmail={form.getValues('email')}
        candidatePhone={form.getValues('phone')}
        initialResumeId={initialResumeId}
        onFinishFace={() => router.push('/facial-setup')}
        onFinishDashboard={() => router.push('/candidate')}
      />
    );
  }

  // Company Email Verification Banner
  if (registeredEmail && selectedRole === 'company') {
    return (
      <Alert className="border-emerald-200 bg-emerald-50 dark:bg-emerald-950/40 text-emerald-900 dark:text-emerald-200 rounded-2xl p-5">
        <MailCheck className="size-5 text-emerald-600 dark:text-emerald-400" />
        <AlertTitle className="font-bold text-sm">Company Account Created!</AlertTitle>
        <AlertDescription className="text-xs mt-1 leading-relaxed">
          We sent a verification link to <strong>{registeredEmail}</strong>. Click the link in the
          email to activate your company workspace. You can also paste the token{' '}
          <Link href="/verify-email" className="font-bold underline text-emerald-700 dark:text-emerald-300">
            here
          </Link>
          .
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-1.5">
      <Form {...form}>
        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-1.5" noValidate>
          {error ? (
            <div className="rounded-xl border border-destructive/30 bg-destructive/10 p-3.5 text-xs text-destructive space-y-2">
              <p className="font-medium">{error}</p>
              {isOffline && (
                <button
                  type="button"
                  onClick={() => form.handleSubmit(onSubmit)()}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-indigo-600 px-3 py-1.5 text-xs font-semibold text-white shadow-xs hover:bg-indigo-700 transition-colors cursor-pointer"
                >
                  <span>Retry connection</span>
                  <ArrowRight className="size-3.5" />
                </button>
              )}
              {isDuplicate && (
                <Link
                  href="/login"
                  className="inline-flex items-center gap-1.5 rounded-lg bg-[#3F5FDE] px-3 py-1.5 text-xs font-semibold text-white shadow-xs hover:bg-[#3252c8] transition-colors"
                >
                  <span>Log in to your account</span>
                  <ArrowRight className="size-3.5" />
                </Link>
              )}
            </div>
          ) : null}

          {/* Full Name / Company Name */}
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem className="space-y-0.5">
                <FormLabel className="text-xs font-bold text-gray-700 dark:text-slate-300">
                  {selectedRole === 'company' ? tr('Nom de l’entreprise', 'Company Name', 'اسم الشركة') : tr('Nom complet', 'Full Name', 'الاسم الكامل')}
                </FormLabel>
                <FormControl>
                  <Input
                    autoComplete="name"
                    placeholder={selectedRole === 'company' ? tr('Nom de l’entreprise', 'Company name', 'اسم الشركة') : tr('Prénom et nom', 'First and last name', 'الاسم واللقب')}
                    className="h-9 rounded-xl border-gray-200 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50 text-sm focus-visible:ring-[#3F5FDE]"
                    {...field}
                  />
                </FormControl>
                <FormMessage className="text-[11px]" />
              </FormItem>
            )}
          />

          {/* Email Address */}
          <FormField
            control={form.control}
            name="email"
            render={({ field }) => (
              <FormItem className="space-y-0.5">
                <FormLabel className="text-xs font-bold text-gray-700 dark:text-slate-300">
                  {tr('Adresse e-mail', 'Email Address', 'البريد الإلكتروني')}
                </FormLabel>
                <FormControl>
                  <Input
                    type="email"
                    autoComplete="email"
                    placeholder="name@example.com"
                    className="h-9 rounded-xl border-gray-200 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50 text-sm focus-visible:ring-[#3F5FDE]"
                    {...field}
                  />
                </FormControl>
                <FormMessage className="text-[11px]" />
              </FormItem>
            )}
          />

          {/* Password */}
          <FormField
            control={form.control}
            name="password"
            render={({ field }) => (
              <FormItem className="space-y-0.5">
                <FormLabel className="text-xs font-bold text-gray-700 dark:text-slate-300">
                  {tr('Mot de passe', 'Password', 'كلمة المرور')}
                </FormLabel>
                <FormControl>
                  <Input
                    type="password"
                    autoComplete="new-password"
                    placeholder="••••••••"
                    className="h-9 rounded-xl border-gray-200 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50 text-sm focus-visible:ring-[#3F5FDE]"
                    {...field}
                  />
                </FormControl>
                <FormMessage className="text-[11px]" />
              </FormItem>
            )}
          />

          {/* Phone */}
          <FormField
            control={form.control}
            name="phone"
            render={({ field }) => (
              <FormItem className="space-y-0.5">
                <FormLabel className="text-xs font-bold text-gray-700 dark:text-slate-300">
                  {tr('Téléphone (facultatif)', 'Phone (optional)', 'الهاتف (اختياري)')}
                </FormLabel>
                <FormControl>
                  <Input
                    autoComplete="tel"
                    placeholder="+216 20 000 000"
                    className="h-9 rounded-xl border-gray-200 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50 text-sm focus-visible:ring-[#3F5FDE]"
                    {...field}
                  />
                </FormControl>
                <FormMessage className="text-[11px]" />
              </FormItem>
            )}
          />

          {/* CV upload — candidate registration */}
          {selectedRole === 'candidate' && (
            <div className="space-y-2">
              <label htmlFor="registration-cv" className="text-xs font-bold text-gray-700 dark:text-slate-300">
                {tr('Comment veux-tu compléter ton profil ?', 'How do you want to complete your profile?', 'كيف تريد إكمال ملفك؟')}
              </label>
              <div className="mx-auto grid w-full max-w-4xl items-stretch gap-1" role="radiogroup" aria-label={tr('Choix du profil', 'Profile setup choice', 'اختيار إعداد الملف')}>
                <div className={`relative flex min-h-[70px] flex-col rounded-xl border transition-colors ${prefillMode === 'upload' ? 'border-[#3F5FDE] bg-indigo-50/70 dark:border-indigo-400 dark:bg-indigo-950/30' : 'border-gray-200 bg-gray-50/50 dark:border-slate-700 dark:bg-slate-800/50'}`}>
                  <button type="button" role="radio" aria-checked={prefillMode === 'upload'} onClick={() => setPrefillMode('upload')} className="w-full p-2 pe-24 text-start"><span className="flex items-center gap-2 text-sm font-semibold"><FileUp className="size-4 text-[#3F5FDE]" />{tr('Préremplir avec mon CV', 'Prefill from my CV', 'ملء من سيرتي')}</span><span className="mt-1 block text-xs text-gray-500 dark:text-slate-400">{tr('Importe ton CV et remplis automatiquement ton profil.', 'Upload your CV and fill your profile automatically.', 'ارفع سيرتك واملأ ملفك آلياً.')}</span></button>
                  {prefillMode === 'upload' && <label htmlFor="registration-cv" className="absolute right-2 top-2 flex cursor-pointer"><span className="shrink-0 rounded-lg bg-white px-3 py-1.5 text-xs font-semibold text-[#3F5FDE] shadow-sm dark:bg-slate-700 dark:text-indigo-300">{tr('Parcourir', 'Browse', 'تصفح')}</span><Input id="registration-cv" type="file" accept=".pdf,.docx,.txt,.md" className="sr-only" onChange={(event) => { const file = event.target.files?.[0] ?? null; if (file && file.size > 10 * 1024 * 1024) { setError('Le CV ne doit pas dépasser 10 Mo.'); setCvFile(null); event.currentTarget.value = ''; return; } setError(null); setCvFile(file); }} /></label>}
                </div>
                <div className="flex items-center gap-3 py-0 text-[11px] font-semibold uppercase tracking-wider text-gray-400 dark:text-slate-500"><span className="h-px flex-1 bg-gray-200 dark:bg-slate-700" /><span>{tr('ou', 'or', 'أو')}</span><span className="h-px flex-1 bg-gray-200 dark:bg-slate-700" /></div>
                <button type="button" role="radio" aria-checked={prefillMode === 'manual'} onClick={() => setPrefillMode('manual')} className={`flex min-h-[78px] w-full flex-col justify-center rounded-xl border p-2.5 text-start transition-colors ${prefillMode === 'manual' ? 'border-[#3F5FDE] bg-indigo-50/70 dark:border-indigo-400 dark:bg-indigo-950/30' : 'border-gray-200 bg-gray-50/50 dark:border-slate-700 dark:bg-slate-800/50'}`}><span className="text-sm font-semibold">{tr('Remplir manuellement', 'Fill manually', 'إدخال يدوي')}</span><span className="mt-1 block text-xs text-gray-500 dark:text-slate-400">{tr('Saisis tes informations toi-même. Tu peux importer un CV plus tard.', 'Enter your information yourself. You can upload a CV later.', 'أدخل معلوماتك بنفسك ويمكنك رفع سيرة لاحقاً.')}</span></button>
              </div>
            </div>
          )}

          {/* Company Website (optional, only for Company mode) */}
          {selectedRole === 'company' && (
            <FormField
              control={form.control}
              name="website"
              render={({ field }) => (
                <FormItem className="space-y-1">
                  <FormLabel className="text-xs font-bold text-gray-700 dark:text-slate-300">
                    Website (optional)
                  </FormLabel>
                  <FormControl>
                    <Input
                      autoComplete="url"
                      placeholder="https://company.com"
                      className="h-10 rounded-xl border-gray-200 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50 text-sm focus-visible:ring-[#3F5FDE]"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage className="text-[11px]" />
                </FormItem>
              )}
            />
          )}

          {/* Submit Button */}
          <button
            type="submit"
            disabled={form.formState.isSubmitting}
            className="w-full flex items-center justify-center gap-2 rounded-xl bg-[#3F5FDE] hover:bg-[#3252c8] text-white py-2.5 px-4 text-xs font-semibold transition-all shadow-md shadow-blue-500/20 cursor-pointer disabled:opacity-50 mt-1"
          >
            {form.formState.isSubmitting ? (
                tr('Création du compte…', 'Creating account...', 'جارٍ إنشاء الحساب…')
            ) : (
              <>
                <span>
                  {selectedRole === 'company' ? tr('Créer le compte entreprise', 'Create Company Account', 'إنشاء حساب شركة') : tr('Créer mon compte candidat', 'Create Candidate Account', 'إنشاء حساب مترشح')}
                </span>
                <ArrowRight className="size-4" />
              </>
            )}
          </button>
        </form>
      </Form>

      <p className="pt-2 text-center text-xs text-gray-500 dark:text-slate-400">
        {tr('Tu as déjà un compte ?', 'Already have an account?', 'لديك حساب؟')}{' '}
        <Link href="/login" className="font-bold text-[#3F5FDE] dark:text-indigo-400 hover:underline">
          {tr('Se connecter', 'Log in', 'تسجيل الدخول')}
        </Link>
      </p>
    </div>
  );
}

